#!/bin/bash
# Generated by Claude Fable 5 (Anthropic)
# Export ONE FISH session from the host PostgreSQL into docker/fishiris/data/<session>/
# as gzip'ed CSV per table (rows WHERE session_id = <session>; tables without a
# session_id column are copied whole), plus the Grafana T0 dashboard JSON.
# The container's entrypoint recreates the schema (scripts/init_fish_pg.sql) and
# COPYs these files back in — no pg_dump/pg_restore version coupling.
#   usage: docker/fishiris/export_session.sh <session_id> [more sessions…]
set -euo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
DSN=${FISH_PG_DSN:-"host=localhost port=5432 dbname=fish user=fish password=fish"}
export PGPASSWORD=$(echo "$DSN" | grep -o "password=[^ ]*" | cut -d= -f2)
PSQL="psql -h $(echo "$DSN" | grep -o "host=[^ ]*" | cut -d= -f2) -p $(echo "$DSN" | grep -o "port=[^ ]*" | cut -d= -f2) -U $(echo "$DSN" | grep -o "user=[^ ]*" | cut -d= -f2) -d $(echo "$DSN" | grep -o "dbname=[^ ]*" | cut -d= -f2) -Atq"
for SID in "$@"; do
  OUT="$HERE/data/$SID"; mkdir -p "$OUT"
  echo "[export] $SID → $OUT"
  # every public table; non-generated columns only (generated columns are recomputed by PG)
  $PSQL -c "SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE' ORDER BY 1" | while read -r T; do
    [ -n "$T" ] || continue
    COLS=$($PSQL -c "SELECT string_agg(quote_ident(column_name), ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='public' AND table_name='$T' AND is_generated='NEVER'")
    HAS_SID=$($PSQL -c "SELECT count(*) FROM information_schema.columns WHERE table_schema='public' AND table_name='$T' AND column_name='session_id'")
    if [ "$HAS_SID" = "1" ]; then WHERE="WHERE session_id='$SID'"; else WHERE=""; fi
    N=$($PSQL -c "SELECT count(*) FROM \"$T\" $WHERE")
    [ "$N" != "0" ] || continue
    echo "$COLS" > "$OUT/$T.cols"
    $PSQL -c "\\copy (SELECT $COLS FROM \"$T\" $WHERE) TO PROGRAM 'gzip -1 > $OUT/$T.csv.gz' CSV"
    printf "  %-24s %10s rows  %s\n" "$T" "$N" "$(du -h "$OUT/$T.csv.gz" | cut -f1)"
  done
done
# Grafana T0 dashboard (uid adq49gh) — Tempo panels dropped (no Tempo in the container)
GRAFANA=${GRAFANA_URL:-http://localhost:3000}; GAUTH=${GRAFANA_AUTH:?set GRAFANA_AUTH=admin:<password> (never commit it)}
curl -s -u "$GAUTH" "$GRAFANA/api/dashboards/uid/adq49gh" > "$HERE/data/T0_dashboard_raw.json"
python3 - "$HERE/data/T0_dashboard.json" "$HERE/data/T0_dashboard_raw.json" <<'PY'
import sys, json
d = json.load(open(sys.argv[2]))["dashboard"]
def ds_type(p):
    ds = p.get("datasource"); return ds.get("type") if isinstance(ds, dict) else None
d["panels"] = [p for p in d.get("panels", []) if p.get("type") != "traces" and "Tempo" not in (p.get("title") or "")]
d.pop("id", None); d["uid"] = "adq49gh"; d["version"] = 1
json.dump(d, open(sys.argv[1], "w"), indent=1)
print(f"[export] T0 dashboard → {sys.argv[1]} ({len(d['panels'])} panels)")
PY
du -sh "$HERE/data"
